/* Lini syntax highlighting — the token palette [SPEC 18].
   Printed by `lini highlight --css`; re-tint a role by redeclaring its variable. */
@layer lini.defaults {
  :root {
    --lini-tok-comment: light-dark(#8a8f98, #6272a4);
    --lini-tok-string: light-dark(#0a7d2c, #f1fa8c);
    --lini-tok-value: light-dark(#8250df, #bd93f9);
    --lini-tok-type: light-dark(#1078a8, #8be9fd);
    --lini-tok-prop: light-dark(#c2185b, #ff79c6);
    --lini-tok-var: light-dark(#b3530b, #ffb86c);
    --lini-tok-op: light-dark(#c2185b, #ff79c6);
    --lini-tok-class: light-dark(#1a7f37, #50fa7b);
    --lini-tok-punct: light-dark(#6e7781, #7b7f9e);
  }
}

.lini-tok-comment {
  color: var(--lini-tok-comment);
  font-style: italic;
}

.lini-tok-string {
  color: var(--lini-tok-string);
}

.lini-tok-number,
.lini-tok-const,
.lini-tok-keyword {
  color: var(--lini-tok-value);
}

.lini-tok-type {
  color: var(--lini-tok-type);
  font-style: italic;
}

.lini-tok-prop {
  color: var(--lini-tok-prop);
}

.lini-tok-type-user {
  color: var(--lini-tok-type);
  font-style: italic;
  opacity: 0.65;
}

.lini-tok-prop-user {
  color: var(--lini-tok-prop);
  opacity: 0.65;
}

.lini-tok-var {
  color: var(--lini-tok-var);
}

.lini-tok-op {
  color: var(--lini-tok-op);
}

.lini-tok-class {
  color: var(--lini-tok-class);
  font-style: italic;
}

.lini-tok-punct {
  color: var(--lini-tok-punct);
}
EXIT 0
<span class="lini-tok-punct">|</span><span class="lini-tok-type">box</span><span class="lini-tok-punct">|</span> <span class="lini-tok-string">&quot;hello&quot;</span>
EXIT 0
<span class="lini-tok-punct">{</span>                                          <span class="lini-tok-comment">// the stylesheet — setup only</span>
  <span class="lini-tok-prop">layout</span><span class="lini-tok-punct">:</span> <span class="lini-tok-keyword">grid</span><span class="lini-tok-punct">;</span>  <span class="lini-tok-prop">columns</span><span class="lini-tok-punct">:</span> <span class="lini-tok-type">repeat</span><span class="lini-tok-punct">(</span><span class="lini-tok-number">2</span><span class="lini-tok-punct">)</span><span class="lini-tok-punct">;</span>  <span class="lini-tok-prop">gap</span><span class="lini-tok-punct">:</span> <span class="lini-tok-number">30</span><span class="lini-tok-punct">;</span>   <span class="lini-tok-comment">// scene config (root declarations)</span>
  <span class="lini-tok-var">--brand</span><span class="lini-tok-punct">:</span> <span class="lini-tok-const">#ff6600</span><span class="lini-tok-punct">;</span>                        <span class="lini-tok-comment">// a themeable colour variable</span>
  w = <span class="lini-tok-number">120</span><span class="lini-tok-punct">;</span>  scale<span class="lini-tok-punct">(</span>n<span class="lini-tok-punct">)</span> = <span class="lini-tok-punct">(</span><span class="lini-tok-number">100</span> * <span class="lini-tok-number">1.2</span>^n<span class="lini-tok-punct">)</span><span class="lini-tok-punct">;</span>      <span class="lini-tok-comment">// bindings — baked numbers / functions</span>
  <span class="lini-tok-punct">|</span><span class="lini-tok-type">box</span><span class="lini-tok-punct">|</span> <span class="lini-tok-punct">{</span> <span class="lini-tok-prop">radius</span><span class="lini-tok-punct">:</span> <span class="lini-tok-number">6</span><span class="lini-tok-punct">;</span> <span class="lini-tok-punct">}</span>                     <span class="lini-tok-comment">// a rule: style every box</span>
  <span class="lini-tok-punct">|</span>-<span class="lini-tok-punct">|</span> <span class="lini-tok-punct">{</span> <span class="lini-tok-prop">stroke</span><span class="lini-tok-punct">:</span> <span class="lini-tok-var">--gray-deep</span><span class="lini-tok-punct">;</span> <span class="lini-tok-punct">}</span>             <span class="lini-tok-comment">// a rule: style every link</span>
  <span class="lini-tok-class">.hot</span> <span class="lini-tok-punct">{</span> <span class="lini-tok-prop">stroke</span><span class="lini-tok-punct">:</span> <span class="lini-tok-var">--red-deep</span><span class="lini-tok-punct">;</span> <span class="lini-tok-punct">}</span>             <span class="lini-tok-comment">// a class definition</span>
  <span class="lini-tok-punct">|</span><span class="lini-tok-type-user">svc</span><span class="lini-tok-op">::</span><span class="lini-tok-type">box</span><span class="lini-tok-punct">|</span> <span class="lini-tok-punct">{</span> <span class="lini-tok-prop">fill</span><span class="lini-tok-punct">:</span> <span class="lini-tok-var">--teal-wash</span><span class="lini-tok-punct">;</span> <span class="lini-tok-prop">stroke</span><span class="lini-tok-punct">:</span> <span class="lini-tok-var">--teal-ink</span><span class="lini-tok-punct">;</span> <span class="lini-tok-punct">}</span>  <span class="lini-tok-comment">// a define: new type over a base</span>
  <span class="lini-tok-punct">|</span><span class="lini-tok-type-user">room</span><span class="lini-tok-op">::</span><span class="lini-tok-type">group</span><span class="lini-tok-punct">|</span> <span class="lini-tok-punct">{</span> <span class="lini-tok-prop">gap</span><span class="lini-tok-punct">:</span> <span class="lini-tok-number">40</span><span class="lini-tok-punct">;</span> <span class="lini-tok-punct">}</span> <span class="lini-tok-punct">[</span>             <span class="lini-tok-comment">// a define with a BODY: intrinsic children + links,</span>
    <span class="lini-tok-punct">|</span><span class="lini-tok-type">box</span><span class="lini-tok-punct">#</span><span class="lini-tok-type">in</span><span class="lini-tok-punct">|</span> <span class="lini-tok-string">&quot;in&quot;</span><span class="lini-tok-punct">;</span> <span class="lini-tok-punct">|</span><span class="lini-tok-type">box</span><span class="lini-tok-punct">#</span><span class="lini-tok-type">out</span><span class="lini-tok-punct">|</span> <span class="lini-tok-string">&quot;out&quot;</span>         <span class="lini-tok-comment">//   re-materialised per instance; ids local,</span>
    in <span class="lini-tok-op">-&gt;</span> out <span class="lini-tok-string">&quot;flows&quot;</span>                      <span class="lini-tok-comment">//   reachable from outside as `garden.out`</span>
  <span class="lini-tok-punct">]</span>
<span class="lini-tok-punct">}</span>

<span class="lini-tok-punct">|</span><span class="lini-tok-type-user">svc</span><span class="lini-tok-punct">#</span><span class="lini-tok-type">api</span><span class="lini-tok-punct">|</span> <span class="lini-tok-string">&quot;API&quot;</span>                            <span class="lini-tok-comment">// instances — the canvas</span>
<span class="lini-tok-punct">|</span><span class="lini-tok-type">cyl</span><span class="lini-tok-punct">#</span><span class="lini-tok-type">db</span><span class="lini-tok-punct">|</span> <span class="lini-tok-string">&quot;Postgres&quot;</span> <span class="lini-tok-punct">{</span> <span class="lini-tok-prop">fill</span><span class="lini-tok-punct">:</span> <span class="lini-tok-var">--rose-wash</span><span class="lini-tok-punct">;</span> <span class="lini-tok-punct">}</span>
<span class="lini-tok-punct">|</span><span class="lini-tok-type-user">room</span><span class="lini-tok-punct">#</span><span class="lini-tok-type">garden</span><span class="lini-tok-punct">|</span>
api <span class="lini-tok-op">-&gt;</span> db <span class="lini-tok-string">&quot;queries&quot;</span> <span class="lini-tok-class">.hot</span>                   <span class="lini-tok-comment">// a link with a label and a worn class</span>
users <span class="lini-tok-op">-&gt;</span> api                               <span class="lini-tok-comment">// undeclared id → auto-creates |box#users| &quot;users&quot;</span>
garden.out <span class="lini-tok-op">-&gt;</span> api                          <span class="lini-tok-comment">// a dot-path into a body</span>
EXIT 0

