input.command:
mkdir -p /tmp/scripts; cat > /tmp/scripts/rules.py <<'EOF'
import sys,glob,re
rules={}
for f in sorted(glob.glob('/tmp/desugar/*.txt')):
    lines=open(f).read().split('\n')
    i=0
    while i<len(lines):
        m=re.match(r'^  (\.lini-[a-z0-9-]+(?:[ .:][^{]*)?) \{$',lines[i])
        if m:
            name=m.group(1); body=[]
            i+=1
            depth=1
            while i<len(lines) and not (lines[i]=='  }' ):
                body.append(lines[i].strip()); i+=1
            b=' '.join(body)
            rules.setdefault(name,{}).setdefault(b,[]).append(f.split('/')[-1])
        i+=1
for k in sorted(rules):
    for b,fs in rules[k].items():
        print(k,'::',b,'  <<',fs[0],len(fs))
EOF
python3 /tmp/scripts/rules.py

