content.content:
// Link markers — the arrow / dot / diamond heads and the full ER cardinality
// set (on any |line| via marker-*, or composed by the crow's-foot operators on
// either end) — plus template-internal links: a |define| whose body links its own
// children, so every instance routes itself.
{
  direction: column; gap: 30; padding: 24; align: start;
  |group| { direction: column; }
  // one specimen line per marker
  |spec::line| { points: -70 0, 70 0; stroke-width: 2; }
  |port::box| { fill: --teal-soft; stroke: --teal-ink; color: --teal-ink; }

  // each |room| materialises its own inlet -> outlet link from the define body
  |room::group| {
    direction: row; gap: 60; padding: 12; fill: --teal-wash; stroke: --teal-ink;
  } [
    |port#inlet| "in"
    |port#outlet| "out"
    inlet -> outlet "flows"
  ]
}

|block| "Markers & internal links" { font-size: 18; font-weight: bold; }

|row| { gap: 44; align: start; } [
  |group#ends| "markers" { gap: 20; } [
    |spec| { marker-end: arrow; stroke: --sky-deep; }
    |spec| { marker-start: dot; marker-end: dot; stroke: --green-deep; }
    |spec| { marker-end: diamond; stroke: --purple-deep; }
  ]
  // the ER cardinality set — the `[min][max]` glyphs, as marker values
  |group#cardinality| "ER cardinality" { gap: 18; } [
    |spec| { marker-end: one; stroke: --sky-deep; }
    |spec| { marker-end: crow; stroke: --sky-deep; }
    |spec| { marker-end: exactly-one; stroke: --blue-deep; }
    |spec| { marker-end: zero-or-one; stroke: --blue-deep; }
    |spec| { marker-end: one-or-many; stroke: --blue-deep; }
    |spec| { marker-end: zero-or-many; stroke: --blue-deep; }
  ]
]

|row| { gap: 52; align: center; } [
  // The same set composes from the crow's-foot operators on **either** end
  // [SPEC 9]: the ring `o` / bar `+` hugs the line, the max glyph (`+` one,
  // `<`/`>` many) is outer.
  |row#rel| { gap: 84; } [
    |caption| "cardinality operators — either end"
    |box#author| "Author"
    |box#book| "Book"
    author +-o< book "writes"
    // one author → zero-or-many books
  ]
  // A chain marks every hop [SPEC 9]: `a -> b <-> c` is exactly `a -> b;
  // b <-> c`, both drawn, each hop carrying its own operator.
  |row#chains| { gap: 44; } [
    |caption| "chains — every hop marked"
    |box#relay| "relay"
    |box#hub| "hub"
    |box#sink| "sink"
    relay -> hub <-> sink
  ]
]

|group#rooms| "template-internal links" { direction: row; gap: 80; } [
  |room#garden| "Garden"
  |room#kitchen| "Kitchen"
]

rooms.garden.outlet -> rooms.kitchen.inlet "carries"
// Positioning & spacing — pin (the 9 named anchor points), translate (a
// post-placement nudge, a tucked badge, exact coordinates), and the 1-, 2- and
// 4-value padding forms. Palette colours.
{
  direction: column; gap: 24; padding: 24; align: start;
  |dot::block| { font-size: 12; }
  |chip::box| { fill: --amber-soft; stroke: --amber-ink; color: --amber-ink; }
  |pad::box| { fill: --green-soft; stroke: --green-ink; color: --green-ink; }
}

// pin: lift a child out of flow and sit it flush on a named point of the parent
|group#anchors| { gap: 8; } [
  |caption| "pin"
  |box#pins| {
    width: 180; height: 120; fill: --sky-wash; stroke: --sky-ink; radius: 8;
  } [
    |dot| "center" { pin: center; color: --teal-ink; }
    |dot| "TL" { pin: top left; color: --rose-ink; }
    |dot| "T" { pin: top; color: --rose-ink; }
    |dot| "TR" { pin: top right; color: --rose-ink; }
    |dot| "L" { pin: left; color: --rose-ink; }
    |dot| "R" { pin: right; color: --rose-ink; }
    |dot| "BL" { pin: bottom left; color: --sky-ink; }
    |dot| "B" { pin: bottom; color: --sky-ink; }
    |dot| "BR" { pin: bottom right; color: --sky-ink; }
  ]
]

// translate: a flow nudge that moves nobody, a badge tucked out over its corner,
// and — with pin: center — exact parent-local coordinates, no size arithmetic
|group#moves| { gap: 14; } [
  |caption| "translate"
  |row| { gap: 14; align: center; } [
    |chip#a| "A"
    |chip#b| "nudged" { translate: 0 12; }
  ]
  |box#card| {
    width: 140; height: 74; fill: --purple-wash; stroke: --purple-ink; color: --purple-ink;
  } [
    "Card"
    |badge| "9" { translate: -4 4; }
    |block| "id 42" { pin: center; translate: 0 24; color: --muted; }
  ]
]

// padding takes 1-, 2-, or 4-value forms, and places the content it insets
|group#spacing| { gap: 10; } [
  |caption| "padding"
  |pad| "scalar"
  |pad| "v h" { padding: 4 14; }
  |pad| "t r b l" { padding: 2 8 16 24; }
]
// Styling — the cascade (element rules < classes < inline), reusable class
// bundles, visual modifiers, and inherited typography. Palette colours.
{
  direction: column; gap: 20; padding: 26;

  // element rules: the lowest-specificity layer, one per shape type
  |box| { radius: 6; fill: --sky-wash; stroke: --sky-ink; color: --sky-ink; }
  |oval| {
    stroke: --teal-ink; stroke-width: 2; fill: --teal-wash; color: --teal-ink;
  }
  |alert::oval| {
    stroke: --red; fill: --red-wash; color: --red-ink; width: 84; height: 46;
  }

  // class bundles, applied with .name
  .thin { stroke-width: 1; }
  .bold { font-weight: bold; }
  .power { stroke: --red; stroke-width: 2.5; }
  .warn { stroke: --orange; stroke-width: 2; }
  .ghost { opacity: 0.35; }
}

|block| "Styles" { font-size: 18; font-weight: bold; }

// element rule, then + a class, then + an inline block — each wins over the last
|group#cascade| { gap: 14; align: center; } [
  |caption| "cascade"
  |box| "element"
  |box| "+ class" .warn
  |box| "+ inline" .warn {
    fill: --amber-wash; stroke: --amber-ink; color: --amber-ink;
  }
  |alert| "alert"
]

|group#classes| { gap: 14; } [
  |caption| "classes"
  |box| "thin" .thin
  |box| "bold" .bold
  |box| "power" .power
  |box| "warn" .warn
  |box| "ghost" .ghost
]

|group#modifiers| { gap: 16; align: center; } [
  |caption| "modifiers"
  |box| "dashed" { stroke-style: dashed; }
  |box| "dotted" { stroke-style: dotted; }
  |box| "multiple" { multiple: 4; }
  |box| "shadow" { shadow: 2 3 5; }
  |box| "rotate" { rotate: -8; }
]

|group#text| { gap: 14; align: center; } [
  |caption| "typography"
  |box| "italic" { font-style: italic; }
  |box| "serif" { font-family: serif; }
  |box| "hsl" { color: hsl(280, 55%, 50%); }
  |box| "upper" { text-transform: uppercase; }
  |box| "under" { text-decoration: underline; }
  |box| "shadow" { text-shadow: 1 1 2 --gray-ink; }
  |box| "spaced" { letter-spacing: 3; }
  |box| "two\nlines" { line-spacing: 12; }
]

