content.content:
// Every drawable primitive plus a few templates, each captioned, in palette
// colours — a soft pastel fill with a matching ink outline. Source for assets/shapes.png.
{
  layout: grid; columns: repeat(4); gap: 26; padding: 30;
  |tile::column| { gap: 9; align: center; }
  |cap::block| { font-size: 12; color: --muted; }
}

|tile| [
  |box| { width: 66; height: 46; fill: --red-wash; stroke: --red-deep; } [
    |badge| "new"
  ]
  |cap| "box + badge"
]
|tile| [
  |rect| { width: 66; height: 46; fill: --orange-wash; stroke: --orange-deep; }
  |cap| "rect"
]
|tile| [
  |oval| { width: 68; height: 54; fill: --amber-wash; stroke: --amber-deep; }
  |cap| "oval"
]
|tile| [
  |hex| { width: 68; height: 58; fill: --lime-wash; stroke: --lime-deep; }
  |cap| "hex"
]

|tile| [
  |slant| { width: 66; height: 46; fill: --green-wash; stroke: --green-deep; }
  |cap| "slant"
]
|tile| [
  |cyl| { width: 58; height: 56; fill: --teal-wash; stroke: --teal-deep; }
  |cap| "cyl"
]
|tile| [
  |diamond| { width: 70; height: 60; fill: --sky-wash; stroke: --sky-deep; }
  |cap| "diamond"
]

|tile| [
  |poly| {
    points: 0 -30, 30 -6, 17 28, -17 28, -30 -6; fill: --purple-wash; stroke: --purple-deep;
  }
  |cap| "poly"
]
|tile| [
  |path| {
    path: "M -32 26 Q 0 -28 32 26"; stroke: --rose-deep; stroke-width: 4;
  }
  |cap| "path"
]
|tile| [
  |line| {
    points: -32 0, 32 0; marker-end: arrow; stroke: --red; stroke-width: 3;
  }
  |cap| "line"
]
|tile| [
  |icon| {
    symbol: house; width: 42; height: 42; fill: --teal-wash; stroke: --teal-deep;
  }
  |cap| "icon"
]

|tile| [
  |group| { padding: 12; } [
    |caption| "Group"
    |box| { width: 56; height: 34; fill: --gray-wash; stroke: --gray-ink; }
    |footnote| "footnote"
  ]
]
|tile| [
  |table| { columns: 24, 24, 24; } [
    "a" "b" "c"
    "d" "e" "f"
  ]
  |cap| "table"
]
|tile| [
  |path| {
    path: "M 0 -28 C 22 -30 31 -12 23 4 C 17 16 30 25 11 30 C -7 34 -27 25 -26 6 C -25 -11 -22 -28 0 -28 Z"; fill: --rose-wash; stroke: --rose-ink; stroke-width: 2;
  }
  |cap| "blob path"
]
// Every built-in template — group, caption, footnote, badge, row, column,
// table (with its auto-header), link — on one captioned board, in palette colours.
{
  direction: column; gap: 22; padding: 26;

  |panel::group| {
    direction: column; gap: 10; padding: 14; fill: --gray-wash; stroke: --gray-soft; radius: 8;
  }
  |tile::box| {
    fill: --sky-soft; stroke: --sky-ink; color: --sky-ink; radius: 6;
  }
}

|block| "Templates" { font-size: 18; font-weight: bold; }

|row#upper| { gap: 22; align: start; } [
  // group with a caption (top edge) and a footnote (bottom edge)
  |panel#profile| [
    |caption| "Profile"
    |tile#name| "Ada Lovelace"
    |tile#role| "Engineer" {
      fill: --teal-soft; stroke: --teal-ink; color: --teal-ink;
    }
    |footnote| "since 1843"
  ]
  // row + column nested inside a group
  |panel#nested| { direction: row; gap: 16; } [
    |caption| "row + column"
    |row| [
      |tile#r1| "a" {
        fill: --amber-soft; stroke: --amber-ink; color: --amber-ink;
      }
      |tile#r2| "b" {
        fill: --amber-soft; stroke: --amber-ink; color: --amber-ink;
      }
    ]
    |column| [
      |tile#c1| "p" {
        fill: --rose-soft; stroke: --rose-ink; color: --rose-ink;
      }
      |tile#c2| "q" {
        fill: --rose-soft; stroke: --rose-ink; color: --rose-ink;
      }
    ]
  ]
]

|row#lower| { gap: 22; align: start; } [
  // a box whose content is text + a badge
  |tile#svc| {
    width: 150; height: 70; fill: --teal-soft; stroke: --teal-ink; color: --teal-ink;
  } [
    "Service"
    |badge| "NEW"
  ]
