// Text & tables [SPEC 3, 5, 6, 8, 9, 12]: a bare "…" is a <text> leaf that
// carries its own text style in place; `max-width:` wraps a card's long label
// to fit — the wrapped size is the measured size, so the grid tracks read it —
// and the holding box's horizontal packing knob flushes the lines (`align` in a
// column box — a card stacks its content [SPEC 11] — or a grid; `justify` in a
// row box); a table's `align` reads one
// value per column, reaching the header band and every body cell; a cell may
// carry its own `{ }` block ("Lime" below — fmt keeps the block and lifts that
// row out of the aligned grid); and a link's [ ] labels are the same styleable
// leaves — `|-|` dresses them all at once, one label overriding in place.

{
  direction: column; gap: 26; padding: 26;
  |-| { stroke: --gray; color: --teal-ink; font-size: 12; font-weight: bold; }
}

"Styleable text, in place" { font-size: 20; font-weight: bold; }

|row#styles| { gap: 16; } [
  "default"
  "coloured" { color: --red-ink; }
  "bold" { font-weight: bold; }
  "italic" { font-style: italic; }
  "underline" { text-decoration: underline; }
]

|row#tables| { gap: 26; } [
  |table#invoice| "Invoice" {
    columns: 130, 70, 100; align: start, center, end;
  } [
    "Item"      "Qty" "Price"
    "Keyboard"  "2"   "$120.00"
    "Monitor"   "1"   "$340.00"
    "USB cable" "5"   "$9.50"
  ]

  |table#stock| "Stock" { columns: 110, 70, 90; } [
    "Item"  "Qty" "State"
    "Apple" "12"  "fresh"
    "Mango" "3"   "ripe"
    "Lime" "0" "out" { color: --red-ink; font-weight: bold; }
  ]
]

|grid#cards| { columns: repeat(3); gap: 14; } [
  |box#c1| "Ship the release notes to every customer" {
    max-width: 150; align: start;
  }
  |box#c2| "Rotate the signing keys before the audit window" { max-width: 150; }
  |box#c3| "Archive dashboards nobody has opened this quarter" {
    max-width: 150; align: end;
  }
]

|box#a| "Alpha"
|box#b| "Beta"
|box#c| "Gamma"

a -> b "styled by |-|"
// wears the global label look — teal, bold, 12
b -> c [
  "nudged & turned" {
    translate: 0 -10; rotate: -6; color: --red-ink; text-shadow: 1 1 2 --gray-ink;
  }
]
// one label overrides — text-shadow rides the label leaf, like any text prop
// Paint [SPEC 6, 10, 11.3]: gradients (two-stop auto-angle, multi-stop,
// explicit angle, radial, gradient-on-stroke, oklch stops), `gap-fill`
// painting the gutters between children (thickness = gap, per-axis), and the
// built-in light/dark theming — every palette var here flips with the OS or a
// `data-theme` toggle. Pick a fixed palette with --theme:
//   lini samples/paint.lini --theme dark --bake-vars -o dark.svg
//   lini theme dark > my-theme.css      // a starting point for your own
{
  direction: column; gap: 26; padding: 26; font-size: 13;

  |card::box| { width: 240; height: 70; stroke: none; color: white; }
}

"Paint — gradients, gutters, themes" { font-size: 18; font-weight: bold; }

|row#r1| { gap: 16; } [
  |card| "gradient(--teal, --blue)" { fill: gradient(--teal, --blue); }
  |card| "three stops, auto-angled" { fill: gradient(--rose, --amber, --sky); }
]

|row#r2| { gap: 16; } [
  |card| "linear-gradient(90, …)" {
    fill: linear-gradient(90, --blue, --purple);
  }
  |card| "radial-gradient(…)" { fill: radial-gradient(--purple, --rose); }
]

|row#r3| { gap: 16; } [
  |card| "gradient on stroke" {
    fill: --gray-wash; color: --gray-ink; stroke: gradient(--teal, --purple); stroke-width: 3;
  }
  |card| "oklch stops" {
    fill: gradient(oklch(0.72, 0.16, 25), oklch(0.72, 0.16, 285));
  }
]

|row#bands| { gap: 12; gap-fill: --sky-soft; } [
  |box#a| "one" { fill: --sky-wash; stroke: --sky-ink; color: --sky-ink; }
  |box#b| "two" { fill: --sky-wash; stroke: --sky-ink; color: --sky-ink; }
  |box#c| "three" { fill: --sky-wash; stroke: --sky-ink; color: --sky-ink; }
]

|grid#week| { columns: 80, 80, 80; gap: 8 0; gap-fill: --teal-ink; } [
  "Mon" "Tue" "Wed"
  "Thu" "Fri" "Sat"
]

|group#service| { gap: 12; } [
  |caption| "Service"
  |box#web| [
    "Web"
    |badge| "v2"
  ]
  |box#api| "API"
  |cyl#db| "Postgres"

  web -> api
  api -> db "query"
]
// Expressions & functions (SPEC §10.7): a (…) group is compile-time math, `=` binds
// a reusable value or function (read in any expression), and a parametric `points:`
// draws a curve. Everything folds to literals at compile time.
{
  direction: column; gap: 20; padding: 24;
  base = 90;
  // a variable — a reusable value, read bare in any expression
  scale(n) = (base * 1.2 ^ n);
  // a reusable size, in terms of the variable
  wave(a, f) = (u * 320, a * sin(2 * pi * f * u));
  // a parametric point
}

|box#a| "scale(0)" {
  width: scale(0); height: 40; fill: --teal-wash; stroke: --teal-ink;
}
|box#b| "scale(3)" {
  width: scale(3); height: 40; fill: --teal-wash; stroke: --teal-ink;
}
|box#pad| "padding 8*2" {
  padding: (8 * 2); fill: --amber-wash; stroke: --amber-ink;
}

// A sine wave from a (…) expression, and the same curve named via wave().
|line#sine| {
  points: (u * 320, 24 * sin(2 * pi * 3 * u)); samples: 64; stroke: --sky-deep; stroke-width: 2;
}
|line#named| {
  points: wave(18, 2); samples: 64; stroke: --rose-deep; stroke-width: 2;
}
{
  direction: column; gap: 64;
}

|column| "Organisation" { layout: tree; } [
  |topic#ceo| "CEO" [
    |topic#cto| "CTO" [
      |topic#backend| "Backend"
      |topic#frontend| "Frontend"
    ]
    |topic#coo| "COO" [
      |topic#ops| "Operations"
      |topic#qa| "Quality"
      ops --- qa
    ]
  ]
]

|column| "Review flow" { layout: tree; direction: row; } [
  |topic#request| "Request" [
    |topic#triage| "Triage" [
      |topic#approve| "Approve"
      |topic#reject| "Reject"
    ]
  ]
]

|column| { layout: tree; direction: bilateral; } [
  |topic#plan| "Launch" [
    |topic#product| "Product" [
      |topic#mvp| "MVP"
      |topic#docs| "Docs"
    ]
    |topic#market| "Marketing" [
      |topic#site| "Site"
    ]
    |topic#sales| "Sales" { side: left; } [
      |topic#leads| "Leads"
    ]
    |topic#ops| "Ops" [
      |topic#legal| "Legal"
    ]
    |topic#team| "Team" [
      |topic#hire| "Hiring"
    ]
  ]
]

