// Scales, axes and formulas [SPEC 14.3–14.5] — the domain side of a chart,
// none of it on the hero board: a `scale: log` axis's decade ticks, a time axis
// reading ISO date literals on a calendar `step:` — and annotated in the same
// literals, a |band| spanning dates and a |mark| landing on one — a `range:` that both crops
// and runs high→low, two value axes sharing one plot (each with its own
// `unit:`, the second declining gridlines so the grid stays single), `format:`
// setting a tick's presentation, a widened `clearance:` standing a chart's text
// off what it labels, a whole-domain `fn:` in `x` that two series
// share through one stylesheet function at 60 `samples:`, and a per-band `fn:`
// list clocked in local `u` across three |band|s.
{
  layout: grid; columns: repeat(2); gap: 36;
  cure(k) = (100 * (1 - exp(-x/k)));
}

|chart| "Requests by tier (req/s)" {
  width: 380; height: 270; categories: "free", "pro", "team", "ent";
} [
  |axis| { side: left; scale: log; }
  |bars| { data: 5, 80, 1200, 45000; }
]

// Date literals make the x axis a time axis; `step: month` lands the ticks on
// calendar boundaries rather than on even spacings of the epoch. A dated domain
// is a domain like any other, so a |band| spans it and a |mark| lands on it in
// the same literals.
|chart| "Weekly active users" { width: 380; height: 270; } [
  |axis#t| { side: bottom; step: month; }
  |axis| "users" { side: left; unit: "k"; }
  |band| "beta" { range: "2026-02-15" "2026-04-01"; fill: --sky; }
  |mark| "GA" { at: "2026-04-06"; axis: t; stroke: --red-deep; }
  |line| "wau" {
    data: "2026-01-05" 12, "2026-02-02" 15, "2026-03-02" 21, "2026-04-06" 28, "2026-05-04" 34, "2026-06-01" 45; marker: dot;
  }
]

// `range: 50 1` does both of its jobs at once: 1 is the top of the chart, so
// the axis runs high→low, and the album's opening week at 62 falls outside the
// window and is cropped to the plot.
|chart| "Chart position" {
  width: 380; height: 270; categories: "Jan", "Feb", "Mar", "Apr", "May", "Jun";
} [
  |axis| "position" { side: left; range: 50 1; }
  |line| "single" { data: 44, 31, 18, 9, 12, 4; marker: circle; }
  |line| "album" { data: 62, 48, 35, 22, 16, 11; marker: circle; }
]

// `clearance:` is the daylight every chrome text keeps off what it labels
// [SPEC 14.6] — the one knob behind the tick rows, the two axis titles, and a
// spoke's category. Widened here so the dual-axis titles breathe; the plot
// gives up the room, never the label.
|chart| "Throughput vs. error rate" {
  width: 380; height: 270; clearance: 10;
  categories: "Mon", "Tue", "Wed", "Thu", "Fri";
} [
  |axis#req| "requests" { side: left; unit: "/s"; }
  |axis#err| "errors" {
    side: right; range: 0 3; unit: "%"; format: decimal 1; gridlines: none;
  }
  |bars| "requests" { data: 820, 932, 901, 1090, 1204; axis: req; }
  |line| "error rate" { data: 2.1, 0.8, 1.5, 0.4, 0.6; axis: err; marker: dot; }
]

// One `cure(k)` binding, two adhesives: the same closed form sampled twice at
// its own time constant, so the pair can never drift apart.
|chart| "Cure strength" { width: 380; height: 270; samples: 60; } [
  |axis| "minutes" { side: bottom; range: 0 90; }
  |axis| { side: left; range: 0 100; unit: "%"; }
  |line| "epoxy" { fn: cure(18); }
  |line| "acrylic" { fn: cure(34); stroke-style: dashed; }
]

// Bands cut the domain into three segments and the series answers with a
// per-band `fn:` list — one expression each, clocked `0 → 1` in local `u`,
// the risers between them drawn because the jump is real.
|chart| "Motor draw (A)" { width: 380; height: 270; } [
  |axis| "phase" { side: bottom; }
  |axis| { side: left; }
  |band| "Close" { range: 0 1.4; fill: --sky; }
  |band| "Inject" { range: 1.4 3.1; fill: --rose; }
  |band| "Hold" { range: 3.1 5.1; fill: --amber; }
  |line| "draw" {
    stroke: --rose-deep; fn: (0.12 + 1.2*exp(-((u-0.8)/0.12)^2)), (1.5 + 3.0*u^1.1), 0.5;
  }
]
// The sketch pen [SPEC 15.3] as a specimen board — nine captioned tiles, one
// feature each. Corner modifiers (`chamfer` / `fillet`) and an even-odd
// `circle()` bore; `angle(deg, n)`'s bearing — 0 up, clockwise — walked round a
// hexagon in 60° steps, the sixth edge left to `close()`; the two-point
// `arc(dx, dy, r)` at its tightest legal radius, `r` exactly half the chord.
// Both readings of `mirror:`: an open subpath **fuses** end-to-end and generates
// its axis `|centerline|`, a closed one is **duplicated**. `pattern:`
// [SPEC 15.4] in both forms — `grid()` located by its first hole, `radial()` by
// the ring centre, which generates its `|pitch-circle|`. The line conventions
// [SPEC 15.7]: a dashed `|hidden|` cut, a manual `|centerline|` overhanging the
// profile, `stroke-style: phantom` for an alternate position. What repeats
// states once — `|view::drawing| { scale: 0.5 }` is the 1 : 2 ratio for all
// nine, `|arm::sketch|` the curve both positions wear — and `justify: end`
// bottoms every tile in its row, so the captions share a baseline. Lini's own
// wordmark drew this pen's first showcase; it lives in `logo.lini` now.
{
  layout: grid; columns: repeat(3); gap: 30 34; justify: end; padding: 30;

  |tile::column| { gap: 10; align: center; }
  |cap::block| { font-size: 12; color: --muted; }
  |view::drawing| { scale: 0.5; }
  |arm::sketch| {
    draw: move(-30, 8) right(16) curve(10, 0, 14, -14, 26, -16) right(18);
    fill: none;
  }
}

|tile| [
  |view| [
    |sketch#plate| {
      draw: move(0, 0) right(52) chamfer(9) down(30) left(52) fillet(9) close()
            move(26, 15) circle(7);
    }
  ]
  |cap| "chamfer · fillet · bore"
]

|tile| [
  |view| [
    |sketch#nut| {
      draw: move(-12, -20.78) angle(90, 24) angle(150, 24) angle(210, 24)
            angle(270, 24) angle(330, 24) close();
    }
  ]
  |cap| "angle — 0 up, clockwise"
]

|tile| [
  |view| [
    |sketch#slot| {
      draw: move(-16, -11) right(32) arc(0, 22, 11) left(32) arc(0, -22, 11)
            close();
    }
  ]
  |cap| "arc — the two-point form"
]

|tile| [
  |view| [
    // Draw the half, get the whole — and the axis centreline with it.
    |sketch#pin| {
      draw: move(-25, 0) up(9) right(20):collar down(4) right(30) down(5);
      mirror: x-axis;
    }
  ]
  |cap| "mirror — fused"
]

|tile| [
  |view| [
    // A closed subpath reflects as a second copy.
    |sketch#clip| {
      draw: move(-24, -10) right(16) down(20) left(16) close();
      mirror: y-axis;
    }
  ]
  |cap| "mirror — twinned"
]

|tile| [
  |view| [
    |sketch#strap| { draw: move(-30, -12) right(60) down(24) left(60) close(); } [
      |hole#bolt| { width: 8; translate: -21 0; pattern: grid(4, 1, 14, 0); }
    ]
  ]
  |cap| "pattern — grid"
]

|tile| [
  |view| [
    |sketch#flange| { draw: move(0, 0) circle(22) circle(7); } [
      |hole#bolt| { width: 6; pattern: radial(6, 14.5); }
    ]
  ]
  |cap| "pattern — radial"
]

|tile| [
  |view| [
    |sketch#body| { draw: move(-26, -14) right(52) down(28) left(52) close(); }
    |hidden#vee| { draw: move(-11, 14) line(11, -15) line(11, 15); }
    |centerline| { points: 0 -20, 0 20; }
  ]
  |cap| "hidden · centre line"
]

|tile| [
  |view| [
    |arm|
    |arm#raised| { translate: 0 -20; stroke-style: phantom; }
  ]
  |cap| "curve · alternate position"
]

