export PATH=$PATH:/tmp/scripts; for s in '→' '⌀' '中' 'a→b' '😀' 'a'; do r "|box| \"$s\"" | grep '<rect'; done; python3 -c "
import sys; sys.path.insert(0,'/tmp/scripts')
from ttf import TTF
t=TTF('/tmp/font_Lini_Sans_500.ttf'); print('notdef',t.adv[0], 'a', t.adv[t.cmap[ord('a')]], 'space', t.adv[t.cmap[32]])
for c in [0x2192,0x2300,0x4e2d]: print(hex(c), c in t.cmap)
"

python3 -c "
import json
r={int(k):v for k,v in json.load(open('/tmp/probe/fallback_widths.json')).items()}
# find ranges
ks=sorted(r)
ranges=[]
cur=None
for k in ks:
    v=r[k]
    if cur and cur[2]==v and k==cur[1]+1: cur[1]=k
    else:
        if cur: ranges.append(cur)
        cur=[k,k,v]
ranges.append(cur)
for a,b,v in ranges:
    if v!=600: print(hex(a),hex(b),v)
" | head -100

export PATH=$PATH:/tmp/scripts; r '|box| "a" .x
|box| "b" .y'; r '|box| "a" { fill: #ab }
|box| "b" { fill: #cd }'; r '"a\x" "b\y"' --json | head -30; r '] ]'; r '|box| "a" { bogus: 1 }'; r '|box| "a" { bogus: 1; width: 5% }'

export PATH=$PATH:/tmp/scripts; r '|box| "a"
{ gap: 5 }' | grep -E 'error|exit'; r '{ gap: 5 }
