cat > /tmp/scripts/tw.py <<'EOF'
import sys; sys.path.insert(0,'/tmp/scripts')
from ttf import TTF
fonts={w:TTF('/tmp/font_Lini_Sans_%d.ttf'%w) for w in (400,500,600,700)}
def tw(s,size=15,w=500):
    t=fonts[w]
    return sum(t.adv[t.cmap[ord(c)]] if ord(c) in t.cmap else 600 for c in s)*size/1000
if __name__=='__main__':
    for s in sys.argv[1:]: print(repr(s), tw(s))
EOF
