.lini-block { fill: none; stroke: none; stroke-width: 2; padding: 0; gap: 36; }
.lini-path { fill: --fill; stroke: --stroke; stroke-width: 2; }
.lini-junction { fill: --wire; stroke: none; width: 8; }
.lini-sch-line { fill: none; stroke: --component-stroke; stroke-width: 1.5; }
.lini-sch-solid { fill: --component-stroke; stroke: none; }
.lini-ref { font-size: 12; font-weight: semibold; }
.lini-component { fill: --component-fill; stroke: --component-stroke; stroke-width: 1.5; radius: 0; padding: 8; prefix: "U"; }
.lini-alt { fill: none; stroke: --group-stroke; stroke-style: dashed; stroke-width: 1; radius: 4; padding: 24; font-size: 12; }
.lini-appliance { stroke: --stroke-dark; stroke-width: 1; fill: --bg; }
.lini-badge { pin: top right; translate: 6 -6; radius: 8; padding: 2 6; shadow: 2 3 3; fill: --accent; color: --accent-text; font-size: 11; font-weight: normal; }
.lini-oval { fill: --fill; stroke: --stroke; stroke-width: 2; padding: 20; direction: column; gap: 12; }
.lini-balloon { width: 16; fill: --fill; stroke: --stroke; font-size: 11; scale: 1; }
.lini-bars { radius: 2; stroke: auto; }
.lini-bath { stroke: --stroke-dark; stroke-width: 1; fill: --bg; }
.lini-bed { stroke: --stroke-dark; stroke-width: 1; fill: --bg; }
.lini-box { fill: --fill; stroke: --stroke; stroke-width: 2; padding: 20; radius: 8; direction: column; gap: 12; }
.lini-caption { pin: top left; translate: 0 -20; color: --caption-color; font-scale: 12 15; font-weight: --caption-font-weight; }
.lini-cell { padding: 4 8; }
.lini-line { fill: none; stroke: --stroke; stroke-width: 2; }
.lini-centerline { stroke-style: center; stroke: --stroke-light; stroke-width: 1; fill: none; }
