mod ast;
mod color;
mod compile;
mod diag;
mod eval;
mod font;
mod layout;
mod lexer;
mod parser;
mod render;
mod scene;
mod style;
mod theme;
mod types;
mod util;

use std::io::{Read, Write};

#[derive(Default, Clone)]
pub struct Options {
    pub output: Option<String>,
    pub format: String,
    pub static_: bool,
    pub embed_font: bool,
    pub check: bool,
    pub json: bool,
    pub theme: Option<String>,
    pub no_fs: bool,
    pub no_warn: bool,
    pub strict: bool,
}

fn read_input(path: &str) -> Result<String, String> {
    if path == "-" {
        let mut s = String::new();
        std::io::stdin().read_to_string(&mut s).map_err(|e| format!("error: <stdin>: {}", e))?;
        return Ok(s);
    }
    match std::fs::read(path) {
        Ok(b) => Ok(String::from_utf8_lossy(&b).into_owned()),
        Err(e) => Err(format!("error: {}: {}", path, e)),
    }
}

pub fn compile_src(src: &str, file: &str, opts: &Options) -> Result<(String, Vec<diag::Diag>), (diag::Diag, Vec<diag::Diag>)> {
    let (doc, _comments) = parser::parse(src).map_err(|e| (e, vec![]))?;
    let sheet = scene::build_sheet(&doc).map_err(|e| (e, vec![]))?;
    let root = compile::root_decls_node(&sheet);
    let mut b = scene::Builder::new(&sheet);
    b.add(root, None);
    b.build_stmts(&doc.stmts, 0).map_err(|e| (e, vec![]))?;
    let nodes = std::mem::take(&mut b.nodes);
    drop(b);
    let mut ctx = compile::Ctx {
        src: src.to_string(),
        file: file.to_string(),
        sheet,
        nodes,
        comp: vec![],
        links: vec![],
        warnings: vec![],
        root_font_size: 15.0,
    };
    compile::compute(&mut ctx);
    ctx.root_font_size = ctx.comp[0].font_size;
    layout::measure(&mut ctx, 0, None);
    let svg = render::render(&ctx, opts).map_err(|e| (e, vec![]))?;
    Ok((svg, ctx.warnings))
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let prog = std::path::Path::new(&args[0]).file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or("lini".into());
    let mut opts = Options { format: "svg".into(), ..Default::default() };
    let mut input: Option<String> = None;
    let mut i = 1;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "-o" | "--output" => {
                i += 1;
                opts.output = args.get(i).cloned();
            }
            "--format" => {
                i += 1;
                opts.format = args.get(i).cloned().unwrap_or_default();
            }
            "--theme" => {
                i += 1;
                opts.theme = args.get(i).cloned();
            }
            "--static" => opts.static_ = true,
            "--embed-font" => opts.embed_font = true,
            "--check" => opts.check = true,
            "--json" => opts.json = true,
            "--no-fs" => opts.no_fs = true,
            "--no-warn" => opts.no_warn = true,
            "--strict" => opts.strict = true,
            "-V" | "--version" => {
                println!("lini 1.1.0");
                return;
            }
            _ => input = Some(a.clone()),
        }
        i += 1;
    }
    let _ = prog;
    let path = match input {
        Some(p) => p,
        None => std::process::exit(3),
    };
    let src = match read_input(&path) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(2);
        }
    };
    let file = if path == "-" { "<stdin>".to_string() } else { path.clone() };
    match compile_src(&src, &file, &opts) {
        Ok((svg, warns)) => {
            if !opts.no_warn {
                for w in &warns {
                    eprintln!("{}", diag::render_text(&file, &src, w));
                }
            }
            let mut so = std::io::stdout();
            let _ = so.write_all(svg.as_bytes());
        }
        Err((e, warns)) => {
            for w in &warns {
                eprintln!("{}", diag::render_text(&file, &src, w));
            }
            eprintln!("{}", diag::render_text(&file, &src, &e));
            std::process::exit(1);
        }
    }
}

