pub fn slot_rank(slot: &str) -> (usize, String) {
    if let Some(rest) = slot.strip_prefix("@define:") {
        let p = SLOT_ORDER.iter().position(|s| *s == "@define").unwrap();
        return (p, rest.to_string());
    }
    if let Some(rest) = slot.strip_prefix("@class:") {
